<script setup>
import { ref, computed, onMounted } from "vue";
import { useRoute, useRouter } from "vue-router";
import { createCommunityPost, getCommunityPost, updateCommunityPost } from "@/features/community/CommunityPostsService";
import { uploadDataUrl } from "@/features/media/MediaService";
const route = useRoute(); const router = useRouter(); const isEdit = computed(() => Boolean(route.params.id));
const form = ref({ title: "", slug: "", body: "", image_url: "", status: "draft" }); const imageFile = ref(null); const imagePreview = ref(""); const loading = ref(false); const saving = ref(false); const error = ref(""); const saved = ref(false);
const slugify = (value) => value.toLowerCase().trim().replace(/[^\w\s-]/g, "").replace(/\s+/g, "-").replace(/-+/g, "-");
const onTitle = () => { if (!isEdit.value || !form.value.slug) form.value.slug = slugify(form.value.title); };
const onImage = (event) => { const file = event.target.files?.[0]; if (!file) return; imageFile.value = file; imagePreview.value = URL.createObjectURL(file); };
const save = async () => { error.value = ""; saved.value = false; if (!form.value.title.trim() || !form.value.slug.trim()) { error.value = "Title and slug are required."; return; } saving.value = true; try { let imageUrl = form.value.image_url; if (imageFile.value) imageUrl = (await uploadDataUrl(await new Promise((resolve, reject) => { const reader = new FileReader(); reader.onload = () => resolve(reader.result); reader.onerror = reject; reader.readAsDataURL(imageFile.value); }), "community")).file; const payload = { ...form.value, image_url: imageUrl }; if (isEdit.value) await updateCommunityPost(route.params.id, payload); else await createCommunityPost(payload); saved.value = true; router.push("/admin/community-posts"); } catch (e) { error.value = e?.response?.data?.message || e.message || "Unable to save community post."; } finally { saving.value = false; } };
onMounted(async () => { if (!isEdit.value) return; loading.value = true; try { const post = (await getCommunityPost(route.params.id)).data; form.value = { title: post.title || "", slug: post.slug || "", body: post.body || "", image_url: post.imageUrl || post.image_url || "", status: post.status || "draft" }; imagePreview.value = form.value.image_url; } catch (e) { error.value = e.message; } finally { loading.value = false; } });
</script>
<template>
  <div class="container-fluid py-4"><div class="d-flex justify-content-between align-items-center mb-4"><div><h1>{{ isEdit ? 'Edit Community Post' : 'Create Community Post' }}</h1><p class="text-muted">Community Posts are separate from News Articles and Announcements.</p></div><button class="btn btn-link" @click="router.push('/admin/community-posts')">Back to Community Posts</button></div>
    <div v-if="loading" class="text-muted">Loading…</div><div v-else class="row g-4"><div class="col-lg-8"><form class="card card-body" @submit.prevent="save"><div v-if="error" class="alert alert-danger">{{ error }}</div><div v-if="saved" class="alert alert-success">Saved.</div><label class="form-label">Title<input v-model="form.title" class="form-control" required @input="onTitle" /></label><label class="form-label">Slug<input v-model="form.slug" class="form-control" required /></label><label class="form-label">Body / caption<textarea v-model="form.body" class="form-control" rows="8" placeholder="Plain text is safest for readers." /></label><label class="form-label">Status<select v-model="form.status" class="form-select"><option value="draft">Draft</option><option value="published">Published</option></select></label><label class="form-label">Image upload<input type="file" accept="image/*" class="form-control" @change="onImage" /></label><label class="form-label">Or image URL<input v-model="form.image_url" type="url" class="form-control" placeholder="https://…" /></label><button class="btn btn-success" :disabled="saving">{{ saving ? 'Saving…' : 'Save Community Post' }}</button></form></div><div class="col-lg-4"><div class="card card-body"><h2 class="h5">Preview</h2><img v-if="imagePreview || form.image_url" :src="imagePreview || form.image_url" :alt="form.title" class="preview-image" /><h3 class="h5 mt-3">{{ form.title || 'Untitled community post' }}</h3><p class="preview-body">{{ form.body || 'Your caption will appear here.' }}</p></div></div></div>
  </div>
</template>
<style scoped>.preview-image { width: 100%; aspect-ratio: 4 / 3; object-fit: cover; border-radius: .4rem; }.preview-body { white-space: pre-wrap; color: #667; }</style>
